"use client";

import { Button } from "@/components/ui/button";
import { getMediaAlt, getMediaUrl } from "@/lib/utils";
import type { HeroBlock as HeroBlockType } from "@/payload-types";
import { ArrowRight } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import Image from "next/image";
import Link from "next/link";
import React from "react";
import { LogoMarkSvg } from "../../layout/logo";

const ELLIPSE_RADIUS = 268; // matches the ellipse's semi-major axis
const ELLIPSE_BOX = { width: 202, height: 538 };
const GALLERY_ANGLES = [0, 45, 90, 135, 180, 225, 270, 315]; // top, going clockwise

/**
 * Calculate the position of gallery images on the ellipse
 * @param angleDeg Angle in degrees (0 = top, increasing clockwise)
 * @param radius Radius of the ellipse tip circle
 * @returns {left: number, top: number} Position of the gallery image
 */
function getPointOnEllipseTips(
  angleDeg: number,
  radius = ELLIPSE_RADIUS,
): { left: number; top: number } {
  const rad = (angleDeg * Math.PI) / 180;
  return {
    left: ELLIPSE_BOX.width / 2 + radius * Math.sin(rad),
    top: ELLIPSE_BOX.height / 2 - radius * Math.cos(rad),
  };
}

/**
 * HeroBlock Component - Displays high-impact landing hero section with main image,
 * title highlights, action CTAs, statistical key metrics, and optional image gallery.
 */
export const HeroBlock: React.FC<HeroBlockType> = ({
  image,
  imageAlt,
  titleBeforeHighlight,
  highlightedTitle,
  titleAfterHighlight,
  subtitle,
  ctaPrimaryText,
  ctaPrimaryHref,
  ctaSecondaryText,
  ctaSecondaryHref,
  stats,
  gallery,
}) => {
  const heroImageUrl = getMediaUrl(image) || "/hero.jpg";
  const heroImageAltText = getMediaAlt(image, imageAlt || "Hero display image");
  const galleryImageUrls = gallery?.map((item) => getMediaUrl(item.image));
  const galleryImageAlts = gallery?.map((item) => getMediaAlt(item.image, "Gallery Icon"));
  const shouldReduceMotion = useReducedMotion();

  return (
    <section
      className="relative overflow-hidden text-white min-h-screen flex flex-col-reverse lg:flex-row items-center pb-20 pt-8"
      id="hero"
    >
      <div className="absolute inset-0 w-full h-full pointer-events-none">
        <Image src={heroImageUrl} alt={heroImageAltText} fill className="object-cover blur-xs" />
      </div>
      <div className="absolute inset-0 w-full h-full pointer-events-none hero-gradient"></div>
      <div className="flex flex-col items-center h-full relative w-full lg:max-w-[55%] px-4 lg:px-10 lg:mt-20">
        <motion.div
          className="flex flex-col gap-8 sm:gap-12 h-full items-start w-full"
          initial="hidden"
          animate="visible"
          variants={{
            hidden: {},
            visible: {
              transition: {
                staggerChildren: 0.15,
              },
            },
          }}
        >
          <div className="flex flex-col gap-6 sm:gap-8 items-start w-full">
            <motion.h2
              variants={{
                hidden: { opacity: 0, y: shouldReduceMotion ? 0 : 30 },
                visible: {
                  opacity: 1,
                  y: 0,
                  transition: { duration: 0.8, ease: [0.16, 1, 0.3, 1] },
                },
              }}
              className="font-semibold text-2xl sm:text-3xl lg:text-5xl lg:leading-[120%] tracking-tighter lg:tracking-[0.03rem] uppercase max-lg:text-center wrap-break-word w-full"
            >
              <span className="text-white">{titleBeforeHighlight}</span>{" "}
              <span className="text-primary-500 relative inline-block">
                {highlightedTitle}{" "}
                <HeroHighlightedTextSvg className="absolute inset-s-0 -bottom-1 w-full" />
              </span>
              {titleAfterHighlight && titleAfterHighlight.length > 0 && (
                <span className="text-white"> {titleAfterHighlight}</span>
              )}
            </motion.h2>
            <motion.p
              variants={{
                hidden: { opacity: 0, y: shouldReduceMotion ? 0 : 20 },
                visible: {
                  opacity: 1,
                  y: 0,
                  transition: { duration: 0.8, ease: [0.16, 1, 0.3, 1] },
                },
              }}
              className="text-sm sm:text-base lg:text-lg max-lg:text-center lg:leading-6 text-white/70"
            >
              {subtitle}
            </motion.p>
            <motion.div
              variants={{
                hidden: { opacity: 0, y: shouldReduceMotion ? 0 : 20 },
                visible: {
                  opacity: 1,
                  y: 0,
                  transition: { duration: 0.8, ease: [0.16, 1, 0.3, 1] },
                },
              }}
              className="flex flex-col sm:flex-row gap-3 sm:gap-5 w-full max-lg:justify-center"
            >
              <motion.div
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                className="w-full sm:w-auto"
              >
                <Button asChild variant="ctaPrimary">
                  <Link href={ctaPrimaryHref}>
                    <span className="font-medium text-white">{ctaPrimaryText}</span>
                    <div className="w-6 h-6 lg:w-7.5 lg:h-7.5 bg-white rounded-full flex items-center justify-center">
                      <ArrowRight
                        className="w-4 h-4 lg:w-5.5 lg:h-5.5 text-primary-500 -rotate-30"
                        width={"22"}
                        height={"22"}
                      />
                    </div>
                  </Link>
                </Button>
              </motion.div>
              <motion.div
                whileHover={{ scale: 1.03 }}
                whileTap={{ scale: 0.97 }}
                className="w-full sm:w-auto"
              >
                <Button asChild variant="ctaSecondary">
                  <Link href={ctaSecondaryHref}>{ctaSecondaryText}</Link>
                </Button>
              </motion.div>
            </motion.div>
          </div>
          <div className="flex flex-col gap-6 sm:gap-10 w-full items-start">
            {stats &&
              stats.length > 0 &&
              stats.map((stat, index) => (
                <motion.div
                  variants={{
                    hidden: { opacity: 0, x: shouldReduceMotion ? 0 : -20 },
                    visible: {
                      opacity: 1,
                      x: 0,
                      transition: { duration: 0.6, ease: [0.16, 1, 0.3, 1] },
                    },
                  }}
                  className="flex flex-row items-center w-full border-s-4 border-primary-500 ps-3 sm:ps-5 gap-3"
                  key={index}
                >
                  <span className="font-medium italic text-2xl sm:text-3xl lg:text-5xl text-white font-display shrink-0">
                    {stat.number}
                  </span>
                  <span className="text-white text-xs sm:text-base lg:text-xl uppercase max-w-88 wrap-break-word">
                    {stat.title}
                  </span>
                </motion.div>
              ))}
          </div>
        </motion.div>
      </div>
      <div className="max-lg:mt-48 max-lg:mb-64 relative h-full flex-1 flex flex-col items-center scale-50 lg:scale-100 transition-transform origin-top lg:origin-center fade-in">
        <LogoMarkSvg
          className="absolute inset-s-1/2 -translate-x-1/2 top-2 translate-y-1/2 text-white z-10"
          width={200}
          height={100}
        />

        {/* Orbiting gallery & ellipses container (rotate) with counter-rotated image divs (inverse rotate) */}
        <motion.div
          className="absolute inset-s-1/2 -translate-x-1/2 -top-40 w-50.5 h-134.5 pointer-events-none"
          style={{ transformOrigin: "center center" }}
          animate={shouldReduceMotion ? { rotate: 0 } : { rotate: 360 }}
          transition={{
            repeat: Infinity,
            duration: 40,
            ease: "linear",
          }}
        >
          <Ellipse className="absolute inset-0" />
          <Ellipse className="absolute inset-0 rotate-90" />
          <Ellipse className="absolute inset-0 rotate-45" />
          <Ellipse className="absolute inset-0 rotate-135" />

          {galleryImageUrls?.map((url, index) => {
            const angle = GALLERY_ANGLES[index % GALLERY_ANGLES.length];
            const { left, top } = getPointOnEllipseTips(angle);
            return (
              <motion.div
                key={index}
                className="w-14 h-14 sm:w-18.5 sm:h-18.5 bg-white rounded-2xl sm:rounded-3xl overflow-hidden absolute flex items-center justify-center pointer-events-auto shadow-lg hover:shadow-xl transition-shadow"
                style={{ left, top, x: "-50%", y: "-50%", transformOrigin: "center center" }}
                animate={shouldReduceMotion ? { rotate: 0 } : { rotate: -360 }}
                transition={{
                  repeat: Infinity,
                  duration: 40,
                  ease: "linear",
                }}
                whileHover={{ scale: 1.12 }}
              >
                <Image
                  src={url || ""}
                  alt={galleryImageAlts?.[index] || ""}
                  width={15}
                  height={15}
                  className="w-8 h-8 sm:w-10 sm:h-10 object-contain"
                />
              </motion.div>
            );
          })}
        </motion.div>
      </div>
    </section>
  );
};

